-- CivicFlow2 shared organization authority.
--
-- Identity comes from Supabase Auth. Authorization never does: a role is a
-- membership row, and every privileged operation re-reads it. Client-supplied
-- roles are ignored everywhere.
--
-- Ids are UUIDs generated by the client. An offline device has to be able to
-- create a shift before it can ask a server for an id, so the primary key is
-- chosen locally and uploaded with the command. Deterministic ids also make a
-- retried create idempotent without a second lookup.

create schema if not exists private;
create schema if not exists sync;

comment on schema private is 'Helper functions. Not exposed through PostgREST.';
comment on schema sync is 'Sync protocol bookkeeping. Not exposed through PostgREST.';

-- One row per auth user. Passwords, sessions and refresh tokens stay in
-- auth.users and are never copied here.
create table public.profiles (
    id uuid primary key references auth.users(id) on delete cascade,
    name text not null check (length(btrim(name)) between 1 and 120),
    email text not null default '',
    created_at timestamptz not null default now(),
    row_version integer not null default 1
);

create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
    insert into public.profiles (id, name, email)
    values (
        new.id,
        coalesce(
            nullif(btrim(new.raw_user_meta_data ->> 'name'), ''),
            nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
            'CivicFlow member'
        ),
        coalesce(new.email, '')
    )
    on conflict (id) do nothing;
    return new;
end;
$$;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function private.handle_new_user();

create table public.organizations (
    id uuid primary key default gen_random_uuid(),
    name text not null check (length(btrim(name)) between 1 and 120),
    initials text not null default '',
    mission text not null default '',
    city text not null default '',
    state text not null default '',
    address text not null default '',
    website text not null default '',
    email text not null default '',
    timezone text not null default 'America/New_York',
    description text not null default '',
    visibility text not null default 'public'
        check (visibility in ('public', 'private')),
    image text,
    image_alt text,
    created_at timestamptz not null default now(),
    created_by uuid references auth.users(id) on delete set null,
    row_version integer not null default 1
);

create table public.organization_contacts (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null references public.organizations(id) on delete cascade,
    email text not null,
    position integer not null default 0,
    unique (organization_id, email)
);

-- Access is a row, not a claim in a token. `membership_epoch` moves whenever
-- role or status changes, so a command created under old authority can be
-- recognised as stale instead of being replayed with privileges it no longer
-- has.
create table public.organization_memberships (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null references public.organizations(id) on delete cascade,
    user_id uuid not null references auth.users(id) on delete cascade,
    role text not null check (role in ('owner', 'coordinator', 'volunteer')),
    status text not null check (status in ('active', 'invited', 'disabled')),
    joined_at timestamptz not null default now(),
    membership_epoch integer not null default 1 check (membership_epoch > 0),
    volunteer_id uuid,
    row_version integer not null default 1,
    unique (organization_id, user_id)
);

create index organization_memberships_user
    on public.organization_memberships (user_id, status);

create table public.organization_invites (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null references public.organizations(id) on delete cascade,
    email text not null default '',
    role text not null check (role in ('coordinator', 'volunteer')),
    token_hash text not null unique,
    created_by uuid references auth.users(id) on delete cascade,
    created_at timestamptz not null default now(),
    expires_at timestamptz not null,
    redeemed_at timestamptz,
    redeemed_by uuid references auth.users(id) on delete set null,
    revoked_at timestamptz,
    row_version integer not null default 1
);

create table public.organization_updates (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null references public.organizations(id) on delete cascade,
    kind text not null check (kind in ('event', 'announcement')),
    title text not null,
    body text not null default '',
    href text not null default '',
    created_at timestamptz not null default now(),
    author_user_id uuid references auth.users(id) on delete set null,
    row_version integer not null default 1
);

create table public.organization_update_reads (
    id uuid primary key default gen_random_uuid(),
    organization_id uuid not null references public.organizations(id) on delete cascade,
    update_id uuid not null references public.organization_updates(id) on delete cascade,
    user_id uuid not null references auth.users(id) on delete cascade,
    read_at timestamptz not null default now(),
    unique (update_id, user_id)
);

-- Cached device state for the health page and for cursor recovery. The cursor
-- is per replica, never per organization: two devices pull at their own pace.
create table sync.devices (
    id uuid primary key,
    organization_id uuid not null references public.organizations(id) on delete cascade,
    user_id uuid not null references auth.users(id) on delete cascade,
    label text not null default '',
    platform text not null default '',
    cursor bigint not null default 0 check (cursor >= 0),
    created_at timestamptz not null default now(),
    last_seen_at timestamptz not null default now(),
    last_successful_sync_at timestamptz,
    pending_operations integer not null default 0,
    oldest_pending_at timestamptz,
    last_error text
);

create index devices_organization on sync.devices (organization_id, last_seen_at desc);

-- One revision for the whole organization. AutoRoster plans record it, and an
-- apply is refused once it has moved. A plan is never merged with a competing
-- plan; it is regenerated.
create table public.organization_revisions (
    organization_id uuid primary key references public.organizations(id) on delete cascade,
    revision bigint not null default 1,
    updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Membership helpers
-- ---------------------------------------------------------------------------

create or replace function private.member_role(p_organization_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
    select m.role
    from public.organization_memberships m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and m.status = 'active'
$$;

create or replace function private.is_member(p_organization_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
    select private.member_role(p_organization_id) is not null
$$;

create or replace function private.is_staff(p_organization_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
    select private.member_role(p_organization_id) in ('owner', 'coordinator')
$$;

create or replace function private.own_volunteer_id(p_organization_id uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
    select m.volunteer_id
    from public.organization_memberships m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and m.status = 'active'
$$;

create or replace function private.membership_epoch(p_organization_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
    select m.membership_epoch
    from public.organization_memberships m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and m.status = 'active'
$$;

-- A single person can volunteer at two organizations, and each roster has its
-- own record for them. Matching on the volunteer row rather than on the user
-- keeps those two profiles separate.
create or replace function private.is_own_volunteer(p_organization_id uuid, p_volunteer_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
    select coalesce(private.own_volunteer_id(p_organization_id) = p_volunteer_id, false)
$$;

-- ---------------------------------------------------------------------------
-- Row versions and membership epochs
-- ---------------------------------------------------------------------------

-- Derived counters travel with a row but must not count as an edit. A
-- registration changing `confirmed` would otherwise invalidate every client
-- that has the shift open, and a coordinator's next edit would report a
-- conflict the user cannot act on.
create or replace function private.touch_row_version()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
    if (to_jsonb(new)
            - 'row_version' - 'updated_at' - 'confirmed' - 'waitlisted'
            - 'filled' - 'hours_verified' - 'events_completed' - 'attendance_rate')
       is distinct from
       (to_jsonb(old)
            - 'row_version' - 'updated_at' - 'confirmed' - 'waitlisted'
            - 'filled' - 'hours_verified' - 'events_completed' - 'attendance_rate')
    then
        new.row_version := old.row_version + 1;
    end if;
    return new;
end;
$$;

create or replace function private.bump_membership_epoch()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
    if new.role is distinct from old.role
       or new.status is distinct from old.status
       or new.volunteer_id is distinct from old.volunteer_id
    then
        new.membership_epoch := old.membership_epoch + 1;
    end if;
    return new;
end;
$$;

-- Every organization keeps one active owner. Without this a coordinator could
-- disable the last owner and leave an organization nobody can administer.
create or replace function private.assert_owner_present()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
    v_organization_id uuid;
begin
    if tg_table_name = 'organization_memberships' then
        v_organization_id := coalesce(
            case when tg_op = 'DELETE' then old.organization_id else new.organization_id end,
            old.organization_id
        );
    end if;

    if v_organization_id is null then
        return null;
    end if;

    if not exists (select 1 from public.organizations where id = v_organization_id) then
        return null;
    end if;

    if not exists (
        select 1 from public.organization_memberships m
        where m.organization_id = v_organization_id
          and m.role = 'owner'
          and m.status = 'active'
    ) then
        raise exception 'an organization must keep an active owner'
            using errcode = 'check_violation';
    end if;

    return null;
end;
$$;

create constraint trigger organization_memberships_keep_owner
after insert or update or delete on public.organization_memberships
deferrable initially deferred
for each row execute function private.assert_owner_present();
